ruleToc.chapterList:
@js:
let novelId = java.hexDecodeToString(result)
//java.log('目录novelId：' + novelId)
function formatChapterLinks(htmlStr) {
  let aTagRegex = /<a\s+href="([^"]+)"[^>]*>([^<]+)<\/a>/g
  let result = []
  let match
  while ((match = aTagRegex.exec(htmlStr)) !== null) {
    let href = match[1]
    let chapName = match[2]
    let chapId = href.replace(/^\/book\//, '').replace(/\.html$/, '').replace('/', 'U')
    result.push({
      href: href,
      chapName: chapName,
      chapId: chapId
    })
  }
  return result
}

let chaps = []
let token = source.getVariable()
if (token) {
  //java.log(`获取${novelId}共享接口章节列表`)
  let result = java.ajax(getApiUrl('/volumelist', { novelId: novelId }, this))
  chaps = JSON.parse(result).data || []
}
if (!chaps.length) {
  try {
    // res = java.ajax(`${source.get('host')}/other/chapters/id/${novelId}.html,{"webview":true}`)
    let res = java.get(`${source.get('host')}/other/chapters/id/${novelId}.html`, { 'user-agent': ua }).body()
    //java.log(res)
    java.setContent(res)
    result = java.getElement(".mulu_list@a||.section-list@a")
    //java.log(result)
  } catch (e) {
    //java.log(`获取${novelId}官网章节列表失败：` + e.message)
  }
  chaps = formatChapterLinks(result)
}
let dirs = []
if (token) {
  try {
    let res = java.ajax(getApiUrl('/dirs', { novelId: novelId }, this))
    dirs = JSON.parse(res).data || []
  } catch { }
}
let dirsData = dirs.reduce((acc, d) => {
  acc[d.chapId] = d
  return acc
}, {})

chaps = chaps.map(v => {
  let chap = dirsData[v.chapId]
  //java.log('chap' + JSON.stringify(chap))
  //java.log('v' + JSON.stringify(v))
  let isShare = !!chap
  let tag = isShare ? '' : ''
  return {
    url: getApiUrl('/chaps', { chapId: v.chapId, novelId: novelId }, this),
    chapName: tag + (chap ? (chap.chapName || v.chapName || v.name || v.title) : (v.chapName || v.name || v.title)),
    vinfo: isShare ? `     ${chap.charCount || 0}字` : '',
  }
})
